input.content:
{
  "name": "macos-fs-watcher",
  "version": "0.1.0",
  "private": true,
  "description": "File-watching tool backed by low-level native macOS filesystem change notifications (FSEvents).",
  "type": "module",
  "main": "src/index.js",
  "bin": {
    "macos-fs-watcher": "src/index.js"
  },
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "start": "node src/index.js"
  },
  "optionalDependencies": {
    "fsevents": "^2.3.3"
  }
}

import { EventEmitter } from 'node:events';
import path from 'node:path';
import fs from 'node:fs';

let fsevents = null;
if (process.platform === 'darwin') {
  try {
    ({ default: fsevents } = await import('fsevents'));
  } catch {
    fsevents = null;
  }
}

export const usingNativeFSEvents = fsevents !== null;

export function watch(root, options = {}) {
  const emitter = new EventEmitter();

  if (fsevents) {
    const stop = fsevents.watch(root, (eventPath, flags, id) => {
      const info = fsevents.getInfo(eventPath, flags, id);
      emitter.emit('all', info);
      emitter.emit(info.event, info);
    });

    emitter.close = () => stop();
    return emitter;
  }

  const watcher = fs.watch(root, { recursive: true }, (eventType, filename) => {
    const info = {
      event: eventType === 'rename' ? 'rename' : 'change',
      path: filename ? path.join(root, filename) : root,
    };
    emitter.emit('all', info);
    emitter.emit(info.event, info);
  });

  emitter.close = () => watcher.close();
  return emitter;
}

#!/usr/bin/env node
import path from 'node:path';
import { watch, usingNativeFSEvents } from './watcher.js';

const target = path.resolve(process.argv[2] ?? process.cwd());

if (!fsExists(target)) {
  console.error(`Not a directory: ${target}`);
  process.exit(1);
}

console.error(
  `Watching ${target} using ${usingNativeFSEvents ? 'native FSEvents' : 'fs.watch fallback'}`,
);

const watcher = watch(target);

watcher.on('all', (info) => {
  console.log(JSON.stringify({ event: info.event, path: info.path }));
});

process.on('SIGINT', () => {
  watcher.close();
  process.exit(0);
});

function fsExists(p) {
  try {
    return require('node:fs').statSync(p).isDirectory();
  } catch {
    return false;
  }
}

